(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zc-sj-prepa-gyneco-j1-sfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zc-sj-prepa-gyneco-j1-sfm\",\n \"titre\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 40,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n   \"sha256\": \"303f77b78935286982a44da88e2f3c5a35ea26f03a43ef4f9c43fd28d90fa86a\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Gynéco-obstétrique · Prépa D.E J1 (SFM)\",\n     \"slug\": \"prepa-gyneco-j1-sfm\",\n     \"pages\": \"\",\n     \"count\": 40,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Gynéco-obstétrique\",\n     \"source\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le petit bassin osseux maternel comprend 3 parties qui sont : le détroit supérieur, le détroit moyen et le détroit inférieur.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Sur le plan obstétrical, le petit bassin (excavation pelvienne) constitue la filière osseuse que traverse le fœtus lors de l'accouchement ; il se subdivise anatomiquement en trois étages successifs : le détroit supérieur (entrée), l'excavation pelvienne avec le détroit moyen (plan des épines sciatiques) et le détroit inférieur (sortie).\\n\\nSource : Cours de Gynéco-Obstétrique — Anatomie du bassin obstétrical.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'ovogonie est un gamète femelle qui a 2 × 22 chromosomes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'ovogonie est une cellule germinale souche diploïde possédant 46 chromosomes (soit 2 × 23 chromosomes : 22 paires d'autosomes et une paire de gonosomes XX), tandis que le gamète femelle mature (ovule) est haploïde avec 23 chromosomes.\\n\\nSource : Cours de Gynéco-Obstétrique — Gamétogenèse et ovogenèse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le repère de la présentation de la face est le menton.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la présentation céphalique défléchie de la face, le repère anatomique qui permet de définir les variétés de position (mento-iliaque gauche ou droite, antérieure ou postérieure) est le menton fœtal.\\n\\nSource : Cours de Gynéco-Obstétrique — Les présentations céphaliques (présentation de la face).\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après la naissance, les premières règles permettent de dater la puberté.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'apparition des premières menstruations (ménarches) constitue l'événement clinique marquant qui permet de dater et d'attester la puberté chez la jeune fille dans l'interrogatoire gynécologique.\\n\\nSource : Cours de Gynéco-Obstétrique — Physiologie du cycle menstruel et puberté.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse normale, le poids de la gestante peut augmenter.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La grossesse normale s'accompagne d'une prise de poids physiologique régulière (en moyenne 9 à 12 kg sur l'ensemble de la grossesse, soit environ 1 kg par mois aux deux premiers trimestres puis 1,5 à 2 kg par mois au troisième trimestre) liée au fœtus, aux annexes et aux réserves maternelles.\\n\\nSource : Cours de Gynéco-Obstétrique — Modifications physiologiques de la grossesse et CPN.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les modifications physiologiques de l'organisme maternel au cours de la grossesse débutent avant la fécondation.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les adaptations physiologiques maternelles de la grossesse sont induites par les sécrétions hormonales du corps jaune gravidique puis du placenta (hCG, progestérone, œstrogènes) ; elles débutent donc après la fécondation et l'implantation de l'œuf.\\n\\nSource : Cours de Gynéco-Obstétrique — Modifications physiologiques de l'organisme maternel pendant la grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les premières règles s'appellent les ménarches.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ».\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune INFAS), Puberté féminine, p. 13 ; DOCUMENT SSR L2 SF 2021 REVU, Consultation en PF (interrogatoire)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La prescription de fer est interdite au 1er trimestre de grossesse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La supplémentation martialo-folique (fer + acide folique) n'est pas contre-indiquée au premier trimestre de grossesse ; elle est au contraire recommandée dès la première consultation prénatale (CPN 1) pour prévenir l'anémie maternelle et les anomalies de fermeture du tube neural.\\n\\nSource : Cours de Gynéco-Obstétrique — Surveillance prénatale et prévention de l'anémie gravidique.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La sérologie de la toxoplasmose positive à IgM témoigne d'une atteinte toxoplasmique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La présence d'immunoglobulines M (IgM) spécifiques anti-Toxoplasma gondii oriente vers une infection toxoplasmique récente ou évolutive (nécessitant un contrôle de la cinétique des IgG et un test d'avidité pour dater précisément la contamination).\\n\\nSource : Cours de Gynéco-Obstétrique — Toxoplasmose et grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au premier trimestre de grossesse, la présence d'IgG à la sérologie de la rubéole signe une primo-infection rubéolique très grave.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Des IgG seules (sans IgM) traduisent une immunité ancienne contre la rubéole : la gestante est protégée. La primo-infection se signe par l'apparition d'IgM ; les réinfections ne sont pas tératogènes. Remarque : Note du sujet : les IgG seules témoignent d'une immunité ancienne.\\n\\nSource : Gynécologie-Obstétrique L3 SF, Primo-infection de la rubéole et grossesse, p. 24-26\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse, l'association d'une TA égale à 15/10 cmHg, d'une protéinurie à 3 croix et d'une crise convulsive signe une pré-éclampsie très sévère.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dès lors qu'une crise convulsive généralisée survient chez une patiente atteinte de pré-éclampsie (HTA gravidique + protéinurie), le tableau clinique n'est plus une simple pré-éclampsie sévère mais devient par définition une crise d'éclampsie (complication paroxystique majeure).\\n\\nSource : Cours de Gynéco-Obstétrique / SONU — Syndromes vasculo-rénaux : pré-éclampsie et éclampsie.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On parle d'hydramnios quand la quantité de liquide amniotique dépasse 2 litres dans les derniers mois de grossesse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hydramnios (ou polyhydramnios) se définit cliniquement et anatomiquement par un excès pathologique de liquide amniotique supérieur à 2 000 ml (2 litres) au troisième trimestre de la grossesse (la quantité physiologique à terme étant comprise entre 500 et 1 000 ml).\\n\\nSource : Cours de Gynéco-Obstétrique — Pathologies des annexes fœtales (hydramnios).\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La survenue d'agitation, de confusion ou de délire durant un paludisme à Plasmodium falciparum au cours de la grossesse traduit automatiquement un paludisme grave.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez la femme enceinte infectée par Plasmodium falciparum, tout trouble neuropsychique (agitation, confusion mentale, obnubilation, délire, convulsions ou coma) constitue un signe clinique de neuropaludisme et classe d'emblée le tableau en paludisme grave nécessitant une prise en charge parentérale en urgence.\\n\\nSource : Cours de Gynéco-Obstétrique — Paludisme et grossesse (critères de gravité).\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse, un taux d'hémoglobine de 10,2 g/100 ml avec une CCMH = 26 et un VGM = 70 µ³ évoque une anémie hypochrome microcytaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Anémie car Hb < 11 g/100 ml ; hypochrome car CCMH < 27 ; microcytaire car VGM < 80 µ³. Ce tableau évoque une anémie ferriprive. Remarque : Le seuil du VGM (< 80 µ³) n'est pas écrit dans l'extrait du cours (connaissance générale).\\n\\nSource : GYNECO L2 IDE VERSION 2025, Anémie et grossesse, p. 38\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il est recommandé de donner une supplémentation en fer à une gestante ayant une hémoglobinose AS à partir du 2e trimestre de grossesse pour éviter une anémie ferriprive.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Contrairement aux syndromes drépanocytaires majeurs (SS, SC, Sβ-thalassémie) où le fer est contre-indiqué en raison du risque de surcharge martiale, la gestante porteuse d'un trait drépanocytaire hétérozygote asymptomatique (AS) doit recevoir une supplémentation en fer et acide folique comme toute femme enceinte pour prévenir l'anémie ferriprive.\\n\\nSource : Cours de Gynéco-Obstétrique — Drépanocytose et grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes suivants, relevez celui ou ceux qui caractérise(nt) le placenta prævia marginal hémorragique dans sa forme typique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Ménorragies indolores faites de sang rouge au 3e trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Métrorragies faites de sang rouge au 3e trimestre de grossesse avec des contractions utérines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Métrorragies indolores faites de sang noir au 3e trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Petit côté des membranes mesurant moins de 10 cm\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Petit côté des membranes mesurant moins de 9 cm\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Métrorragies faites de sang rouge vif au 3e trimestre de grossesse avec des contractions utérines\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. D. Petit côté des membranes mesurant moins de 10 cm\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Anatomiquement, l'insertion basse du placenta (placenta prævia latéral ou marginal) est affirmée après la délivrance lorsque la mesure du petit côté des membranes (distance entre l'orifice de rupture des membranes et le bord le plus proche du placenta) est inférieure à 10 cm. Sur le plan clinique, les métrorragies du placenta prævia sont spontanées, indolores, faites de sang rouge vif et sans contractions utérines (les options a, b, c et f sont donc inexactes).\\n\\nSource : Cours de Gynéco-Obstétrique — Hémorragies du 3e trimestre : le placenta prævia.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Relevez la ou les manœuvre(s) à exécuter pour extraire la tête dernière retenue dans l'excavation pelvienne lors de l'accouchement du siège.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Attitude de VERMELIN\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Petite extraction du siège\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Grande extraction du siège\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Manœuvre de BRACHT\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Manœuvre de LOVSET\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Manœuvre de MAURICEAU\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F. Manœuvre de MAURICEAU\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"La manœuvre de Mauriceau est la manœuvre obstétricale spécifique permettant de fléchir, orienter et extraire la tête dernière lorsque celle-ci est retenue dans l'excavation pelvienne au cours d'un accouchement du siège. La manœuvre de Lovset sert au dégagement des épaules/bras relevés et l'attitude de Vermelin correspond à l'abstention interventionniste lors de l'expulsion spontanée.\\n\\nSource : Cours de Gynéco-Obstétrique / SONU — Accouchement en présentation du siège.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le cycle menstruel commence toujours :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Au 1er jour de survenue des règles\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Au début des règles\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. À la fin des règles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. À l'ovulation\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Au dernier jour précédant les règles\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Au 1er jour des ménarches\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A. Au 1er jour de survenue des règles ; B. B. Au début des règles\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Le cycle menstruel commence au 1er jour des règles (début des règles) et va jusqu'au dernier jour précédant les règles suivantes.\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune INFAS), Cycle menstruel normal, p. 26 ; DOCUMENT SSR L2 SF 2021 REVU, Méthode du calendrier\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la présentation de la face, on sent toujours au toucher vaginal :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. La grande fontanelle du fœtus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. La petite fontanelle du fœtus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Le front du fœtus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Le menton du fœtus\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Les yeux du fœtus\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. La bouche du fœtus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C. Le front du fœtus ; D. D. Le menton du fœtus ; E. E. Les yeux du fœtus ; F. F. La bouche du fœtus\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Dans la présentation de la face, on ne sent pas de fontanelle : on perçoit les éléments de la face (yeux, nez, bouche, menton). Le menton est le repère. Remarque : Le cours cite « les yeux, le nez, la bouche et le menton » ; il ne cite pas le front, que la correction nationale retient aussi.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Les différentes présentations (face)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après la réfection de l'épisiotomie, le ou les soins ci-dessous ne doivent pas être prodigués :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Faire un bain de siège à l'eau froide\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Appliquer en permanence un linge mouillé sur la suture\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Assécher la suture\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Faire un pansement occlusif sur la suture\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Faire un pansement non occlusif sur la suture\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Faire un bain de siège à l'eau tiède ou chaude sur la suture\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A. Faire un bain de siège à l'eau froide ; B. B. Appliquer en permanence un linge mouillé sur la suture ; D. D. Faire un pansement occlusif sur la suture ; F. F. Faire un bain de siège à l'eau tiède ou chaude sur la suture\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Après la réfection, le périnée doit rester sec : toilette vulvaire biquotidienne puis séchage, compresse stérile et garniture propre, pas de bain de siège. Sont donc à éviter : bain de siège (froid ou chaud), linge mouillé en permanence, pansement occlusif. Assécher la suture et faire un pansement non occlusif sont recommandés.\\n\\nSource : GYNECO L2 IDE VERSION 2025, Suites de couches (soins en cas d'épisiotomie), p. 84 ; COURS DE SOINS OBSTETRICAUX 2e année SF, Suites de couches normales\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, relevez celle ou celles qui sont fausses.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Le cordon ombilical contient 3 vaisseaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Le fibrome utérin involue à la ménopause\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Le fibrome utérin est une cause de stérilité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Le liquide amniotique est produit principalement par le fœtus\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. À terme, le poids du placenta est égal au 1/6 du poids du fœtus\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Le cordon ombilical s'insère sur la face maternelle du placenta\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C. Le fibrome utérin est une cause de stérilité ; F. F. Le cordon ombilical s'insère sur la face maternelle du placenta\",\n       \"answerLetters\": [\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"Propositions fausses : C et F. Le cordon s'insère sur la face fœtale du placenta (pas sur la face maternelle). Vraies : 3 vaisseaux (2 artères, 1 veine), poids du placenta = 1/6 du poids de l'enfant, régression du fibrome après la ménopause. Remarque : Le cours L2 IDE cite comme signes du fibrome les ménorragies et les avortements à répétition, sans parler de stérilité ; dire que le fibrome « est une cause de stérilité » est une généralisation que la correction nationale juge fausse.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Examen du placenta ; GYNECO L2 IDE VERSION 2025, Le fibrome utérin, p. 125\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les facteurs suivants, relevez celui ou ceux qui sont classiquement des facteurs de risque du cancer du col utérin.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Cervicite virale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Réalisation régulière des examens de dépistage\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Partenaires sexuels multiples\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Nulliparité\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Premier accouchement après 30 ans\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Antécédents de cancer du col chez la mère\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A. Cervicite virale ; C. C. Partenaires sexuels multiples\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Le cancer du col est viro-induit (HPV 16 et 18, HSV2) et lié au comportement sexuel : cervicite virale et multiplicité des partenaires sont des facteurs de risque. Le dépistage régulier protège ; la nulliparité et le 1er accouchement tardif n'en font pas partie (c'est la grande multiparité avec 1er enfant avant 20 ans qui est citée).\\n\\nSource : GYNECO L2 IDE VERSION 2025, Cancer du col de l'utérus, p. 49\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes suivants évoquent une grossesse molaire :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Métrorragies spontanées de sang rouge au cours du 1er trimestre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Métrorragies spontanées de sang noir au cours du 1er trimestre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Métrorragies provoquées de sang rouge au cours du 1er trimestre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Sialorrhée et vomissements au 1er trimestre associés à un placenta ressemblant à des œufs de grenouille\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Aménorrhée\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Ménorragie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A. Métrorragies spontanées de sang rouge au cours du 1er trimestre ; D. D. Sialorrhée et vomissements au 1er trimestre associés à un placenta ressemblant à des œufs de grenouille ; E. E. Aménorrhée\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"La môle hydatiforme se manifeste au premier trimestre sur un fond d'aménorrhée gravidique par des métrorragies spontanées récidivantes faites de sang rouge, des signes sympathiques de grossesse exacerbés (vomissements incoercibles, sialorrhée liés à l'hyper-sécrétion de β-hCG) et l'expulsion caractéristique de vésicules translucides en grappe de raisin ou « frai de grenouille ».\\n\\nSource : Cours de Gynéco-Obstétrique — Môle hydatiforme (p. 131).\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__23\",\n       \"num\": \"24\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Ce jour à 5 h, Mme B.B.B., 30 ans, G6 P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail a commencé à 4 h. Hauteur utérine = 36 cm. Température = 36,9 °C. Le col est dilaté à 5 cm. Taux d'hémoglobine = 10 g/100 ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 h 20 min à une fille pesant 4000 g ; à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 h 30 min sans GATPA, par traction contrôlée du cordon. Mme B.B.B. risque de saigner abondamment et de mourir.\",\n       \"text\": \"Parmi les propositions suivantes, relevez le ou les gestes à exécuter vis-à-vis de ce nouveau-né.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Massage cardiaque externe\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Demander de l'aide et expliquer doucement à la mère les gestes à faire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Couper aussitôt le cordon ombilical avant 1 min de vie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Bien placer le nouveau-né en décubitus dorsal, le cou en extension modérée\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Libérer les voies aériennes\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Administrer des médicaments pour faire respirer ce nouveau-né\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Demander de l'aide et expliquer doucement à la mère les gestes à faire ; D. D. Bien placer le nouveau-né en décubitus dorsal, le cou en extension modérée ; E. E. Libérer les voies aériennes\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Devant un nouveau-né en asphyxie néonatale qui ne crie pas et ne respire pas à la naissance, les premiers gestes de réanimation néonatale de base (SONU) consistent à appeler à l'aide et rassurer/informer la mère, installer le nouveau-né séché et réchauffé en décubitus dorsal avec la tête en position neutre (cou en légère extension) et désobstruer/libérer les voies aériennes supérieures avant d'initier la ventilation au ballon et au masque.\\n\\nSource : Cours SONU / Pédiatrie — Réanimation du nouveau-né en salle de naissance.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__24\",\n       \"num\": \"25\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Ce jour à 5 h, Mme B.B.B., 30 ans, G6 P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail a commencé à 4 h. Hauteur utérine = 36 cm. Température = 36,9 °C. Le col est dilaté à 5 cm. Taux d'hémoglobine = 10 g/100 ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 h 20 min à une fille pesant 4000 g ; à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 h 30 min sans GATPA, par traction contrôlée du cordon. Mme B.B.B. risque de saigner abondamment et de mourir.\",\n       \"text\": \"Grâce à ces gestes correctement exécutés, le nouveau-né a une ventilation spontanée efficace et durable. Vous décidez néanmoins de surveiller l'accouchée et son nouveau-né. Entre 5 h 30 et 7 h 30, chez la mère, vous allez surveiller :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Les lochies pour rechercher une endométrite du post-partum\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. La TA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Le pouls\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. L'écoulement vulvaire pour rechercher un saignement anormal\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Le globe de sécurité\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Les conjonctives pour rechercher un ictère\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. La TA ; C. C. Le pouls ; D. D. L'écoulement vulvaire pour rechercher un saignement anormal ; E. E. Le globe de sécurité\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Dans les 2 heures qui suivent la délivrance, on surveille l'hémorragie : état général (TA, pouls), globe de sécurité et écoulement vulvaire. Les lochies d'endométrite et l'ictère se surveillent plus tard, dans les suites de couches.\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune INFAS), Suites de couches normales, p. 84 ; Soins à l'accouchée, p. 98-99\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__25\",\n       \"num\": \"26\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Ce jour à 5 h, Mme B.B.B., 30 ans, G6 P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail a commencé à 4 h. Hauteur utérine = 36 cm. Température = 36,9 °C. Le col est dilaté à 5 cm. Taux d'hémoglobine = 10 g/100 ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 h 20 min à une fille pesant 4000 g ; à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 h 30 min sans GATPA, par traction contrôlée du cordon. Mme B.B.B. risque de saigner abondamment et de mourir.\",\n       \"text\": \"En dehors de tout élément anormal, la fréquence normale de cette surveillance entre 6 h 30 et 7 h 30 est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Toutes les 10 min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Toutes les 15 min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Toutes les 30 min\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Toutes les 40 min\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Toutes les 60 min\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Toutes les 20 min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. Toutes les 30 min\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « toutes les 30 min » pour la 2e heure après la délivrance. Remarque : Note du sujet : 15 min la 1re heure, 30 min la 2e heure. Les cours ne disent pas tous la même chose : le cours L1 (p. 84) écrit « toutes les 30 mn pendant 2 heures », alors que le cours L1 (p. 99) et le cours SO écrivent « toutes les 15 min pendant les 2 premières heures ».\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune INFAS), Suites de couches normales, p. 84 ; COURS DE SOINS OBSTETRICAUX 2e année SF, Le suivi post-natal\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__26\",\n       \"num\": \"27\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Ce jour à 5 h, Mme B.B.B., 30 ans, G6 P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail a commencé à 4 h. Hauteur utérine = 36 cm. Température = 36,9 °C. Le col est dilaté à 5 cm. Taux d'hémoglobine = 10 g/100 ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 h 20 min à une fille pesant 4000 g ; à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 h 30 min sans GATPA, par traction contrôlée du cordon. Mme B.B.B. risque de saigner abondamment et de mourir.\",\n       \"text\": \"À 6 h, Mme B.B.B. a saigné 100 ml par voie vaginale ; elle transpire abondamment, sa TA = 6/4 cmHg, son pouls = 120/min, ses conjonctives sont blanches, sans ictère, et le périnée est intact. Selon vous, de quoi souffre Mme B.B.B. ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Hémorragie du post-partum\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Hémorragie du post-partum immédiat\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Hémorragie du post-partum tardif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Hémorragie du post-partum immédiat par atonie utérine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Hémorragie du post-partum immédiat par trouble de la coagulation\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Hémorragie du post-partum immédiat par déchirure périnéale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A. Hémorragie du post-partum ; B. B. Hémorragie du post-partum immédiat ; D. D. Hémorragie du post-partum immédiat par atonie utérine\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Une perte sanguine qui retentit sur l'état de la mère (sueurs, TA 6/4, pouls 120, conjonctives pâles) est une HPP quelle que soit la quantité. Elle survient dans les 24 h : HPP immédiat. Sans GATPA, chez une grande multipare avec gros enfant et travail rapide, et avec un périnée intact, la cause la plus probable est l'atonie utérine (70 % des cas).\\n\\nSource : GYNECO L2 IDE VERSION 2025, Hémorragie du post-partum, p. 73-74\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__27\",\n       \"num\": \"28\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Ce jour à 5 h, Mme B.B.B., 30 ans, G6 P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail a commencé à 4 h. Hauteur utérine = 36 cm. Température = 36,9 °C. Le col est dilaté à 5 cm. Taux d'hémoglobine = 10 g/100 ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 h 20 min à une fille pesant 4000 g ; à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 h 30 min sans GATPA, par traction contrôlée du cordon. Mme B.B.B. risque de saigner abondamment et de mourir.\",\n       \"text\": \"Parmi les propositions suivantes, relevez chez Mme B.B.B. le ou les facteurs de risque de survenue de cette pathologie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Mme B.B.B. admise à 5 h avec un col dilaté à 5 cm\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Taux d'hémoglobine = 10 g/100 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Accouchement d'un garçon pesant 4000 g\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Hauteur utérine = 36 cm\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Début du travail à 4 h et naissance à 5 h 20 min\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Hauteur utérine = 37 cm\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. D. Hauteur utérine = 36 cm ; E. E. Début du travail à 4 h et naissance à 5 h 20 min\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Facteurs de risque d'atonie utérine présents : surdistension utérine (HU 36 cm, gros enfant) et travail trop rapide (1 h 20). C est fausse (l'enfant est une fille) et F aussi (la HU est de 36 cm, pas 37). Remarque : La grande multiparité (G6 P5) est aussi un facteur de risque, mais elle n'est pas proposée.\\n\\nSource : GYNECO L2 IDE VERSION 2025, Hémorragie du post-partum (facteurs de risque de l'atonie), p. 74\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__28\",\n       \"num\": \"29\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Ce jour à 5 h, Mme B.B.B., 30 ans, G6 P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail a commencé à 4 h. Hauteur utérine = 36 cm. Température = 36,9 °C. Le col est dilaté à 5 cm. Taux d'hémoglobine = 10 g/100 ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 h 20 min à une fille pesant 4000 g ; à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 h 30 min sans GATPA, par traction contrôlée du cordon. Mme B.B.B. risque de saigner abondamment et de mourir.\",\n       \"text\": \"Parmi les propositions suivantes, relevez chez Mme B.B.B. le ou les facteurs de risque d'aggravation de cette pathologie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Mme B.B.B. admise à 5 h avec un col dilaté à 5 cm\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Mme B.B.B. non obèse, paroi abdominale mince\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Accouchement d'un garçon pesant 4000 g\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Hauteur utérine à 36 cm\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Début du travail à 4 h et naissance à 5 h 20 min\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Taux d'hémoglobine = 10 g/100 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F. Taux d'hémoglobine = 10 g/100 ml\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"L'anémie antérieure non compensée (Hb 10 g/100 ml) est l'un des « 2 ennemis » de l'HPPI : elle aggrave le retentissement du saignement et le risque de décès.\\n\\nSource : GYNECO L2 IDE VERSION 2025, Hémorragie du post-partum, p. 74\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__29\",\n       \"num\": \"30\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Ce jour à 5 h, Mme B.B.B., 30 ans, G6 P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail a commencé à 4 h. Hauteur utérine = 36 cm. Température = 36,9 °C. Le col est dilaté à 5 cm. Taux d'hémoglobine = 10 g/100 ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 h 20 min à une fille pesant 4000 g ; à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 h 30 min sans GATPA, par traction contrôlée du cordon. Mme B.B.B. risque de saigner abondamment et de mourir.\",\n       \"text\": \"Le premier geste à exécuter pour arrêter ce saignement par voie vaginale chez Mme B.B.B. est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Révision utérine suivie de délivrance artificielle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Perfusion intraveineuse de 5 unités de Syntocinon (ocytocine)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Révision utérine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Perfusion intraveineuse d'antibiotiques et de 5 unités de Syntocinon (ocytocine)\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Délivrance artificielle suivie de révision utérine\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Délivrance artificielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. Révision utérine\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le placenta est déjà délivré (5 h 30) : il faut d'abord vérifier que l'utérus est vide et le faire se rétracter, donc faire une révision utérine (puis massage et ocytocine). La délivrance artificielle n'a pas lieu d'être. Remarque : Dans le cours SO, la prise d'une voie veineuse précède la révision utérine.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, CAT devant les HPP (atonie utérine) ; GYNECO L2 IDE VERSION 2025, HPP, p. 74\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__30\",\n       \"num\": \"31\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 — Vous recevez ce jour à 6 h, dans la maternité rurale où vous exercez, Mme C.C.C., 27 ans, 4e geste, 3e pare, sans antécédent particulier, pour des contractions utérines sur grossesse à terme. Elle a 3 contractions utérines en 10 minutes, chacune dure 40 secondes ; le col est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Ici, il s'agit d'une :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Présentation du sommet\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Présentation du siège\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Présentation du siège décomplété\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Présentation de la face tournée vers le sacrum\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Présentation du siège complet\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Présentation céphalique avec procidence des 2 pieds\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. E. Présentation du siège complet\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"Les 2 pieds sont perçus dans l'aire de dilatation : c'est un siège complet (mode des pieds, fœtus assis en tailleur). Remarque : B (siège) est aussi juste, mais la correction nationale retient la réponse la plus précise.\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune INFAS), Présentations fœtales, p. 57 ; SONU L3 SF, Accouchement du siège, p. 68\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__31\",\n       \"num\": \"32\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 — Vous recevez ce jour à 6 h, dans la maternité rurale où vous exercez, Mme C.C.C., 27 ans, 4e geste, 3e pare, sans antécédent particulier, pour des contractions utérines sur grossesse à terme. Elle a 3 contractions utérines en 10 minutes, chacune dure 40 secondes ; le col est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Ici, le repère de cette présentation est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. L'occiput du fœtus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. La racine du nez fœtal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Le sacrum du fœtus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. La petite fontanelle du fœtus\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Le menton du fœtus\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Le sacrum de la parturiente\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. Le sacrum du fœtus\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le repère de la présentation du siège est le sacrum du fœtus (S.I.D.A. = sacro-iliaque droite antérieure).\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune INFAS), Présentations fœtales, p. 60\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__32\",\n       \"num\": \"33\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 — Vous recevez ce jour à 6 h, dans la maternité rurale où vous exercez, Mme C.C.C., 27 ans, 4e geste, 3e pare, sans antécédent particulier, pour des contractions utérines sur grossesse à terme. Elle a 3 contractions utérines en 10 minutes, chacune dure 40 secondes ; le col est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Relevez la ou les phrases vraies concernant le cas de Mme C.C.C.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Dès la fin de mon examen, je commence à remplir le partographe modifié de l'OMS\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'OMS, car l'état de la poche des eaux n'est pas précisé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Dès la fin de mon examen, je ne commence pas à remplir le partographe modifié de l'OMS, car il ne s'agit pas d'une présentation eutocique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'OMS\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'OMS, car il s'agit d'une présentation en S.I.D.A.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'OMS, car je suis en périphérie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. Dès la fin de mon examen, je commence à remplir le partographe modifié de l'OMS\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Col à 5 cm avec 3 CU/10 min : la patiente est en phase active ; le partographe se démarre dès le début de la phase active, y compris pour un siège.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Partographe ; SONU L3 SF, Accouchement du siège (« remplir le partographe »), p. 69\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__33\",\n       \"num\": \"34\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 — Vous recevez ce jour à 6 h, dans la maternité rurale où vous exercez, Mme C.C.C., 27 ans, 4e geste, 3e pare, sans antécédent particulier, pour des contractions utérines sur grossesse à terme. Elle a 3 contractions utérines en 10 minutes, chacune dure 40 secondes ; le col est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Concernant Mme C.C.C., relevez la ou les phrases synonymes d'organisation de son transfert depuis son admission à la maternité.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Poche des eaux intacte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Rupture intempestive des membranes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Rupture précoce des membranes à 5 cm\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Bruits du cœur fœtal = 140/min, réguliers, et liquide amniotique méconial\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Rupture prématurée des membranes\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Rupture des membranes à 10 cm de dilatation cervicale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C. Rupture précoce des membranes à 5 cm ; E. E. Rupture prématurée des membranes\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient C et E : une rupture des membranes avant dilatation complète, dans un siège complet, expose à la procidence du cordon et impose l'organisation du transfert.\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune INFAS), Mécanisme de l'accouchement (rupture prématurée, précoce, tempestive), p. 68\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__34\",\n       \"num\": \"35\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 — Vous recevez ce jour à 6 h, dans la maternité rurale où vous exercez, Mme C.C.C., 27 ans, 4e geste, 3e pare, sans antécédent particulier, pour des contractions utérines sur grossesse à terme. Elle a 3 contractions utérines en 10 minutes, chacune dure 40 secondes ; le col est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Indiquez le ou les gestes à exécuter chez Mme C.C.C. dès que le col utérin est dilaté à 10 cm.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Pratiquer une large épisiotomie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Perfusion intraveineuse de 5 unités de Syntocinon (ocytocine) pour renforcer les contractions utérines et empêcher le relèvement des bras du fœtus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Perfusion intraveineuse de 5 unités de Syntocinon (ocytocine) pour dilater le col utérin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Faire une grande extraction du siège en l'absence de souffrance fœtale aiguë\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Surtout ne pas rompre la poche des eaux\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Injection intramusculaire de 10 unités de Syntocinon (ocytocine)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Perfusion intraveineuse de 5 unités de Syntocinon (ocytocine) pour renforcer les contractions utérines et empêcher le relèvement des bras du fœtus\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"À dilatation complète dans le siège, on met 5 UI d'ocytocine dans la perfusion pour renforcer les contractions et éviter le relèvement des bras. L'épisiotomie se fait plus tard (quand le siège appuie sur le périnée) et on rompt la poche si elle est encore intacte.\\n\\nSource : SONU L3 SF, Accouchement du siège (dispositions pendant le travail), p. 69\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__35\",\n       \"num\": \"36\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 — Vous recevez ce jour à 6 h, dans la maternité rurale où vous exercez, Mme C.C.C., 27 ans, 4e geste, 3e pare, sans antécédent particulier, pour des contractions utérines sur grossesse à terme. Elle a 3 contractions utérines en 10 minutes, chacune dure 40 secondes ; le col est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est S.I.D.A. et le bassin est normal.\",\n       \"text\": \"À un moment donné, vous décidez de pratiquer une large épisiotomie. Indiquez le moment idéal pour réaliser ce geste.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Quand la tête fœtale est visible durant une contraction utérine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Quand la tête fœtale est visible en dehors d'une contraction utérine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Quand l'anus fœtal est dilaté à 2-3 cm durant une contraction utérine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Quand l'anus maternel est dilaté à 2-3 cm durant une contraction utérine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Dès que le siège prend contact avec le périnée maternel, ou quand il fait bomber le périnée et que la hanche antérieure commence à se dégager, ou quand on voit l'anus fœtal durant une contraction utérine\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Quand le col utérin est dilaté à 10 cm durant une contraction utérine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. E. Dès que le siège prend contact avec le périnée maternel, ou quand il fait bomber le périnée et que la hanche antérieure commence à se dégager, ou quand on voit l'anus fœtal durant une contraction utérine\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"L'épisiotomie large et systématique du siège se fait dès que la présentation appuie sur le périnée (siège qui fait bomber le périnée, hanche antérieure qui se dégage, anus fœtal visible pendant la contraction).\\n\\nSource : SONU L3 SF, Accouchement du siège, p. 69\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__36\",\n       \"num\": \"37\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 — Vous recevez ce jour à 6 h, dans la maternité rurale où vous exercez, Mme C.C.C., 27 ans, 4e geste, 3e pare, sans antécédent particulier, pour des contractions utérines sur grossesse à terme. Elle a 3 contractions utérines en 10 minutes, chacune dure 40 secondes ; le col est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Parmi les gestes suivants, relevez celui qui doit être exécuté durant la réparation d'une épisiotomie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Suturer les 3 plans avec du nylon n°1\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Suturer les 3 plans avec du nylon n°2\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Suturer les 3 plans avec du fil non résorbable non serti n°1\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Commencer toujours la suture par la profondeur du vagin pour venir vers la vulve\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Ne pas suturer l'angle supérieur de l'incision vaginale\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Réaliser la suture en un seul plan\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. Commencer toujours la suture par la profondeur du vagin pour venir vers la vulve\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La réfection d'une épisiotomie s'effectue plan par plan (muqueuse vaginale, plan musculaire profond, peau) avec du fil résorbable (Vicryl®), en débutant impérativement 1 cm au-dessus de l'angle supérieur de l'incision au fond du vagin pour progresser de la profondeur vers la vulve afin d'assurer une hémostase parfaite.\\n\\nSource : Cours de Gynéco-Obstétrique — Technique de réfection de l'épisiotomie.\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 — Vous recevez ce jour à 6 h, dans la maternité rurale où vous exercez, Mme C.C.C., 27 ans, 4e geste, 3e pare, sans antécédent particulier, pour des contractions utérines sur grossesse à terme. Elle a 3 contractions utérines en 10 minutes, chacune dure 40 secondes ; le col est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Au cours de l'expulsion de ce fœtus en présentation du siège, vous décidez de terminer rapidement l'expulsion par une manœuvre, malgré l'absence de toute dystocie. Relevez la phrase exacte.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Je pratique la manœuvre de Mauriceau dès que je vois la pointe des omoplates du fœtus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Je pratique la manœuvre de Bracht dès que je vois la pointe des omoplates du fœtus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Je pratique systématiquement la manœuvre de Lovset\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Je pratique la manœuvre de Mauriceau dès que je vois les oreilles du fœtus\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Je pratique la petite extraction du siège\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Je pratique la manœuvre de Bracht dès que je vois les oreilles du fœtus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Je pratique la manœuvre de Bracht dès que je vois la pointe des omoplates du fœtus\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La manœuvre de Bracht se fait dès l'apparition de la pointe des omoplates à la vulve : on relève le fœtus sans traction vers le ventre maternel. Mauriceau est réservée à la tête retenue, Lovset au relèvement des bras.\\n\\nSource : SONU L3 SF, Accouchement du siège (manœuvre de Bracht), p. 71-72\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 — Vous recevez ce jour à 6 h, dans la maternité rurale où vous exercez, Mme C.C.C., 27 ans, 4e geste, 3e pare, sans antécédent particulier, pour des contractions utérines sur grossesse à terme. Elle a 3 contractions utérines en 10 minutes, chacune dure 40 secondes ; le col est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Pour le score d'Apgar à 1 minute du nouveau-né, vous avez coté 2 pour la fréquence cardiaque et 1 pour chacun des autres paramètres. Le total du score d'Apgar à 1 minute est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 7\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 5\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 3\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 4\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. 9\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. 6\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F. 6\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"Le score d'Apgar additionne 5 paramètres notés de 0 à 2 : 2 (fréquence cardiaque) + 4 × 1 = 6. Remarque : Note du sujet : 2 + (4 × 1) = 6.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Soins au nouveau-né (indice d'Apgar)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j1-sfm__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 2 — Vous recevez ce jour à 6 h, dans la maternité rurale où vous exercez, Mme C.C.C., 27 ans, 4e geste, 3e pare, sans antécédent particulier, pour des contractions utérines sur grossesse à terme. Elle a 3 contractions utérines en 10 minutes, chacune dure 40 secondes ; le col est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Après la fin de l'accouchement de Mme C.C.C., vous suspectez une rupture utérine ; pour lever ce doute, vous réalisez :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Perfusion intraveineuse de 5 unités de Syntocinon (ocytocine)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Délivrance artificielle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Perfusion intraveineuse d'antibiotiques et de 5 unités de Syntocinon (ocytocine)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Délivrance artificielle suivie de révision utérine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Révision utérine\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Révision utérine suivie de délivrance artificielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. E. Révision utérine\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"La révision utérine (main dans l'utérus) explore le fond, les faces et les bords et contrôle la vacuité et l'intégrité de l'utérus : c'est elle qui confirme ou écarte une rupture utérine.\\n\\nSource : SONU L3 SF, Délivrance artificielle et révision utérine, p. 49 ; GYNECO L2 IDE VERSION 2025, HPP (« voir avec la main »), p. 74\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Gynécologie SFM\",\n       \"sourceFile\": \"J1_SFM_Gynecologie_SRPF_corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
